using EFootwear.BLL.Contacts.Contracts;

namespace EFootwear.BLL.Customers.Contracts;

/// <summary>
/// New Customer. The name and the phone number are required; the email, the birth date, the city and the CNIC are optional. A customer sent
/// without a type is regular. The code is generated by the server.
/// </summary>
public sealed record CreateCustomerRequest(
    string Name,
    string? Phone,
    string? Email,
    DateOnly? BirthDate,
    Guid? CityId,
    string StatusCode,
    ContactOpeningBalanceRequest? OpeningBalance,
    string? Cnic = null,
    string? CustomerTypeCode = null) : ICustomerEditableFields;
